import"chrome://resources/cr_elements/cr_button/cr_button.js";import"chrome://resources/cr_elements/cr_dialog/cr_dialog.js";import"./certificate_shared.css.js";import{I18nMixin}from"chrome://resources/cr_elements/i18n_mixin.js";import{assertNotReached}from"chrome://resources/js/assert.js";import{loadTimeData}from"chrome://resources/js/load_time_data.js";import{PolymerElement}from"chrome://resources/polymer/v3_0/polymer/polymer_bundled.min.js";import{getTemplate}from"./certificate_delete_confirmation_dialog.html.js";import{CertificatesBrowserProxyImpl,CertificateType}from"./certificates_browser_proxy.js";const CertificateDeleteConfirmationDialogElementBase=I18nMixin(PolymerElement);export class CertificateDeleteConfirmationDialogElement extends CertificateDeleteConfirmationDialogElementBase{static get is(){return"certificate-delete-confirmation-dialog"}static get template(){return getTemplate()}static get properties(){return{model:Object,certificateType:String}}getTitleText_(){const getString=localizedMessageId=>loadTimeData.getStringF(localizedMessageId,this.model.name);switch(this.certificateType){case CertificateType.PERSONAL:return getString("certificateManagerDeleteUserTitle");case CertificateType.SERVER:return getString("certificateManagerDeleteServerTitle");case CertificateType.CA:return getString("certificateManagerDeleteCaTitle");case CertificateType.OTHER:return getString("certificateManagerDeleteOtherTitle");default:assertNotReached()}}getDescriptionText_(){const getString=loadTimeData.getString.bind(loadTimeData);switch(this.certificateType){case CertificateType.PERSONAL:return getString("certificateManagerDeleteUserDescription");case CertificateType.SERVER:return getString("certificateManagerDeleteServerDescription");case CertificateType.CA:return getString("certificateManagerDeleteCaDescription");case CertificateType.OTHER:return"";default:assertNotReached()}}onCancelClick_(){this.$.dialog.close()}onOkClick_(){CertificatesBrowserProxyImpl.getInstance().deleteCertificate(this.model.id).then((()=>{this.$.dialog.close()}),(error=>{if(error===null){return}this.$.dialog.close();this.dispatchEvent(new CustomEvent("certificates-error",{bubbles:true,composed:true,detail:{error:error,anchor:null}}))}))}}customElements.define(CertificateDeleteConfirmationDialogElement.is,CertificateDeleteConfirmationDialogElement);